const LocaleContext = createContext(null);

function getStoredLanguage() {
  try {
    const stored = localStorage.getItem(LANGUAGE_STORAGE_KEY);
    return supportedLanguages.includes(stored) ? stored : 'en';
  } catch {
    return 'en';
  }
}

export function hasSavedLanguagePreference() {
  try {
    return supportedLanguages.includes(localStorage.getItem(LANGUAGE_STORAGE_KEY));
  } catch {
    return false;
  }
}

export function LocaleProvider({ children }) {
  const [language, setLanguageState] = useState(getStoredLanguage);

  const setLanguage = useCallback((nextLanguage) => {
    if (!supportedLanguages.includes(nextLanguage)) return;
    setLanguageState(nextLanguage);
    try {
      localStorage.setItem(LANGUAGE_STORAGE_KEY, nextLanguage);
    } catch (error) {
      console.error('Could not persist language preference', error);
    }
  }, []);

  const t = useCallback((text, values = {}) => {
    if (typeof text !== 'string' || language === 'en') return text;
    const dictionary = translations[language] || {};
    const prefix = Object.keys(dictionary)
      .filter((key) => key.endsWith(':') && text.startsWith(key))
      .sort((left, right) => right.length - left.length)[0];
    const translated = dictionary[text] ?? (prefix ? `${dictionary[prefix]}${text.slice(prefix.length)}` :
      text.startsWith('GPS detected (') && dictionary["GPS detected"]
        ? `${dictionary["GPS detected"]}${text.slice("GPS detected".length)}`
        : text);
    return translated.replace(/\{(\w+)\}/g, (match, key) =>
      Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : match
    );
  }, [language]);

  const formatDate = useCallback((date, options) => {
    const locale = language === 'mr' ? 'mr-IN' : language === 'hi' ? 'hi-IN' : 'en-IN';
    return new Intl.DateTimeFormat(locale, options).format(date);
  }, [language]);

  const formatNumber = useCallback((number, options) => {
    const locale = language === 'mr' ? 'mr-IN' : language === 'hi' ? 'hi-IN' : 'en-IN';
    return new Intl.NumberFormat(locale, options).format(number);
  }, [language]);

  const value = useMemo(() => ({
    language,
    setLanguage,
    hasStoredLanguagePreference: hasSavedLanguagePreference(),
    t,
    formatDate,
    formatNumber,
    languages: supportedLanguages
  }), [language, setLanguage, t, formatDate, formatNumber]);

  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useI18n() {
  const context = useContext(LocaleContext);
  if (!context) throw new Error('useI18n must be used within LocaleProvider');
  return context;
}

export function translateKnown(text, language) {
  if (language === 'en' || typeof text !== 'string') return text;
  return translations[language]?.[text] ?? text;
}
